import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ----------------------------------------------------------------------
# CUDA kernel (fp16 matrix multiplication)
# ----------------------------------------------------------------------
cpp_source = r'''
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>

void matmul_fp16_cuda(at::Tensor A, at::Tensor B, at::Tensor C);
'''

cuda_source = r'''
#include <torch/extension.h>
#include <cuda_fp16.h>

#define BLOCK_SIZE 16

__global__ void matmul_fp16_kernel(const half* __restrict__ A,
                                   const half* __restrict__ B,
                                   half* __restrict__ C,
                                   int M, int K, int N) {
    int row = blockIdx.y * BLOCK_SIZE + threadIdx.y;
    int col = blockIdx.x * BLOCK_SIZE + threadIdx.x;

    if (row >= M || col >= N) return;

    float acc = 0.0f;
    for (int k = 0; k < K; ++k) {
        half a = A[row * K + k];
        half b = B[k * N + col];
        acc += __half2float(a) * __half2float(b);
    }
    C[row * N + col] = __float2half(acc);
}

void matmul_fp16_cuda(at::Tensor A, at::Tensor B, at::Tensor C) {
    const int M = A.size(0);
    const int K = A.size(1);
    const int N = B.size(1);

    const dim3 block(BLOCK_SIZE, BLOCK_SIZE);
    const dim3 grid((N + BLOCK_SIZE - 1) / BLOCK_SIZE,
                    (M + BLOCK_SIZE - 1) / BLOCK_SIZE);

    const half* A_ptr = reinterpret_cast<const half*>(A.data_ptr<at::Half>());
    const half* B_ptr = reinterpret_cast<const half*>(B.data_ptr<at::Half>());
    half* C_ptr = reinterpret_cast<half*>(C.data_ptr<at::Half>());

    AT_CUDA_CHECK(cudaGetLastError());
    matmul_fp16_kernel<<<grid, block, 0, at::cuda::getCurrentCUDAStream()>>>(
        A_ptr, B_ptr, C_ptr, M, K, N);
    AT_CUDA_CHECK(cudaGetLastError());
}
'''

# Compile the extension
_matmul_ext = load_inline(name='matmul_fp16_ext',
                          cpp_sources=cpp_source,
                          cuda_sources=cuda_source,
                          functions=['matmul_fp16_cuda'],
                          verbose=False)

