# PyTorch model using the custom kernel
# ----------------------------------------------------------------------
class ModelNew(nn.Module):
    """
    Drop‑in replacement for the reference Model, using a custom fp16 CUDA kernel.
    """
    def __init__(self):
        super().__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        # Ensure inputs are on CUDA, contiguous, and fp16
        A = A.to(dtype=torch.float16, device='cuda', non_blocking=True).contiguous()
        B = B.to(dtype=torch.float16, device='cuda', non_blocking=True).contiguous()

